#include "exercise.h"
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <ctype.h>
#include <math.h>
#include "exercise.h"
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <ctype.h>
typedef struct json {char*key,*text;double number;struct json**children;size_t count;int kind;} json;
static void jf(json*j){if(!j)return;free(j->key);free(j->text);for(size_t i=0;i<j->count;i++)jf(j->children[i]);free(j->children);free(j);}
static void ws(const char**p){while(isspace((unsigned char)**p))(*p)++;}
static int hex(char c){return c>='0'&&c<='9'?c-'0':c>='a'&&c<='f'?c-'a'+10:c>='A'&&c<='F'?c-'A'+10:-1;}
static bool unicode(const char**p,unsigned*value){*value=0;for(int i=0;i<4;i++){int d=hex(**p);if(d<0)return false;*value=*value*16+(unsigned)d;(*p)++;}return true;}
static char*js(const char**p){if(**p!='"')return NULL;(*p)++;char*s=(char*)malloc(strlen(*p)+1);size_t n=0;while(**p&&**p!='"'){char c=*(*p)++;if(c=='\\'){if(!**p){free(s);return NULL;}c=*(*p)++;if(c=='u'){unsigned v;if(!unicode(p,&v)){free(s);return NULL;}if(v>=0xd800&&v<=0xdbff){if((*p)[0]!='\\'||(*p)[1]!='u'){free(s);return NULL;}*p+=2;unsigned low;if(!unicode(p,&low)||low<0xdc00||low>0xdfff){free(s);return NULL;}v=0x10000+(v-0xd800)*1024+low-0xdc00;}if(v<0x80)s[n++]=(char)v;else if(v<0x800){s[n++]=(char)(0xc0|(v>>6));s[n++]=(char)(0x80|(v&63));}else if(v<0x10000){s[n++]=(char)(0xe0|(v>>12));s[n++]=(char)(0x80|((v>>6)&63));s[n++]=(char)(0x80|(v&63));}else{s[n++]=(char)(0xf0|(v>>18));s[n++]=(char)(0x80|((v>>12)&63));s[n++]=(char)(0x80|((v>>6)&63));s[n++]=(char)(0x80|(v&63));}continue;}if(c=='n')c='\n';else if(c=='t')c='\t';else if(c=='r')c='\r';else if(c=='b')c='\b';else if(c=='f')c='\f';else if(c!='"'&&c!='\\'&&c!='/'){free(s);return NULL;}}s[n++]=c;}if(**p!='"'){free(s);return NULL;}(*p)++;s[n]=0;return s;}
static json*jp(const char**p){ws(p);json*j=(json*)calloc(1,sizeof(json));if(**p=='"'){j->kind=1;j->text=js(p);if(!j->text){jf(j);return NULL;}}else if(**p=='{'||**p=='['){char close=**p=='{'?'}':']';j->kind=close=='}'?2:3;(*p)++;ws(p);while(**p!=close){char*key=NULL;if(j->kind==2){key=js(p);ws(p);if(!key||**p!=':'){free(key);jf(j);return NULL;}(*p)++;}json*c=jp(p);if(!c){free(key);jf(j);return NULL;}c->key=key;j->children=(json**)realloc(j->children,(j->count+1)*sizeof(json*));j->children[j->count++]=c;ws(p);if(**p==close)break;if(**p!=','){jf(j);return NULL;}(*p)++;ws(p);}(*p)++;}else{char*end;j->number=strtod(*p,&end);if(end==*p){jf(j);return NULL;}*p=end;}return j;}
static json*field(json*j,const char*k){if(!j)return NULL;for(size_t i=0;i<j->count;i++)if(j->children[i]->key&&!strcmp(j->children[i]->key,k))return j->children[i];return NULL;}
static void add(char**s,const char*t){size_t a=strlen(*s),b=strlen(t);*s=(char*)realloc(*s,a+b+1);memcpy(*s+a,t,b+1);}
static void quoted(char**s,const char*t){add(s,"\"");for(;*t;t++){char c[10]={*t,0};if(*t=='"'||*t=='\\'){c[0]='\\';c[1]=*t;}else if((unsigned char)*t<32)snprintf(c,sizeof c,"\\u%04x",(unsigned char)*t);add(s,c);}add(s,"\"");}
static size_t index_of(const rest_api*a,const char*s){for(size_t i=0;i<a->count;i++)if(!strcmp(a->names[i],s))return i;return a->count;}
static size_t user_add(rest_api*a,const char*s){size_t old=a->count,k=index_of(a,s);if(k<old)return k;a->names=(char**)realloc(a->names,(old+1)*sizeof(char*));a->names[old]=(char*)malloc(strlen(s)+1);strcpy(a->names[old],s);double*d=(double*)calloc((old+1)*(old+1),sizeof(double));for(size_t i=0;i<old;i++)for(size_t j=0;j<old;j++)d[i*(old+1)+j]=a->debts[i*old+j];free(a->debts);a->debts=d;a->count++;return old;}
void rest_free(rest_api*a){for(size_t i=0;i<a->count;i++)free(a->names[i]);free(a->names);free(a->debts);memset(a,0,sizeof *a);}
bool rest_init(rest_api*a,const char*s){memset(a,0,sizeof *a);if(!s)return true;json*j=jp(&s),*u=field(j,"users");if(!j||!u||u->kind!=3){jf(j);return false;}for(size_t i=0;i<u->count;i++){json*n=field(u->children[i],"name");if(!n||!n->text){jf(j);rest_free(a);return false;}user_add(a,n->text);}for(size_t i=0;i<u->count;i++){json*o=field(u->children[i],"owes");if(o)for(size_t k=0;k<o->count;k++){json*d=o->children[k];size_t b=index_of(a,d->key);if(b<a->count)a->debts[i*a->count+b]=d->number;}}jf(j);return true;}
static size_t*sorted(rest_api*a){size_t*i=(size_t*)malloc(a->count*sizeof(size_t));for(size_t k=0;k<a->count;k++)i[k]=k;for(size_t x=0;x<a->count;x++)for(size_t y=x+1;y<a->count;y++)if(strcmp(a->names[i[x]],a->names[i[y]])>0){size_t t=i[x];i[x]=i[y];i[y]=t;}return i;}
static char*object(rest_api*a,size_t user){char*s=(char*)calloc(1,1);add(&s,"{\"name\":");quoted(&s,a->names[user]);double balance=0;size_t*order=sorted(a);for(int side=0;side<2;side++){add(&s,side?",\"owed_by\":{":",\"owes\":{");bool first=true;for(size_t k=0;k<a->count;k++){size_t other=order[k];double value=side?a->debts[other*a->count+user]:a->debts[user*a->count+other];balance+=side?value:-value;if(value<=0)continue;if(!first)add(&s,",");first=false;quoted(&s,a->names[other]);char n[100];snprintf(n,100,":%.15g",value);add(&s,n);}add(&s,"}");}free(order);char n[100];snprintf(n,100,",\"balance\":%.15g}",balance==0?0:balance);add(&s,n);return s;}
static char*users(rest_api*a,bool*include){char*s=(char*)calloc(1,1);add(&s,"{\"users\":[");size_t*order=sorted(a);bool first=true;for(size_t k=0;k<a->count;k++){size_t i=order[k];if(include&&!include[i])continue;if(!first)add(&s,",");first=false;char*t=object(a,i);add(&s,t);free(t);}free(order);add(&s,"]}");return s;}
char*rest_get(rest_api*a,const char*url,const char*payload){if(strcmp(url,"/users"))return NULL;if(!payload)return users(a,NULL);json*j=jp(&payload),*u=field(j,"users");if(!u){jf(j);return NULL;}bool*include=(bool*)calloc(a->count,sizeof(bool));for(size_t i=0;i<u->count;i++){if(!u->children[i]->text)continue;size_t k=index_of(a,u->children[i]->text);if(k<a->count)include[k]=true;}char*s=users(a,include);free(include);jf(j);return s;}
char*rest_post(rest_api*a,const char*url,const char*payload){if(!payload)return NULL;json*j=jp(&payload);char*s=NULL;if(!strcmp(url,"/add")){json*u=field(j,"user");if(u&&u->text)s=object(a,user_add(a,u->text));}else if(!strcmp(url,"/iou")){json*l=field(j,"lender"),*b=field(j,"borrower"),*amount=field(j,"amount");if(l&&l->text&&b&&b->text&&amount){size_t x=index_of(a,l->text),y=index_of(a,b->text);if(x<a->count&&y<a->count&&x!=y&&amount->number>=0){double net=a->debts[y*a->count+x]-a->debts[x*a->count+y]+amount->number;a->debts[y*a->count+x]=net>0?net:0;a->debts[x*a->count+y]=net<0?-net:0;bool*include=(bool*)calloc(a->count,sizeof(bool));include[x]=include[y]=true;s=users(a,include);free(include);}}}jf(j);return s;}

